41	        { id: 1, targetType: 'PROJECT', targetId: 1, at: '2024-03-10T09:00:00Z', text: 'Kickoff meeting notes' }, // middle
42	        { id: 2, targetType: 'PROJECT', targetId: 1, at: '2024-05-20T09:00:00Z', text: 'Final review' }, // newest
43	        { id: 3, targetType: 'PROJECT', targetId: 1, at: '2024-01-05T09:00:00Z', text: 'Initial brief' }, // oldest
44	        { id: 4, targetType: 'PROJECT', targetId: 2, at: '2024-06-01T09:00:00Z', text: 'Other project note' },
